INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1076290-chem102', 'stk-king_of_net', 'CHEM 102', 'info', '{"desc": "أنا بكتب بشكل عام وانتوا عليكم الاستنتاج 😏\n\nكتاب المادة هو نفسه كتاب Chem 101\nوالكتاب ممتاز من ناحية كثرة الأمثلة وتنوعها\nعشان نكون واضحين معاكم المادة أصعب من Chem 101\nبس ما يعني إنك ماتقدر تجيب فيها قريد\nإذا شديت حيلك وذاكرتها أول بأول إن شاء الله بيتسهل لك الـ A+ أو على الأقل B+\nومن أهم التشابترات الي لازم تركز فيها من ناحية المذاكرة بفهم\nتشابر 17 وتشابتر 19 وتشابتر 10 وتشابتر 25\nوبرضو فيها كم تشابتر قراءة لين تطفش\nوإذا تبغى نصيحتي حاول تحل شوية من أسئلة الكتاب الي تجي في آخر التشابتر\nلأنها تبين لنفسك إنت فاهم ولا ماعندك سالفة 😁\nوطبعا مثل مو معروف الكويزات عليها 17.5 % يعني ذاكر لها كأنك تذاكر لميجر\n\nهذا الي كان في بالي وإن شاء الله إني أفدتكم 👍", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/chem-102-general-chemistry-ii/120590/2", "user": "KinG_OF_NeT", "ts": 1344217620000, "tid": 120590, "pn": 2}}', 1344217620000, 1794766199, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1076302-chem102', 'stk-user4492', 'CHEM 102', 'info', '{"desc": "^ +1\n\nالمادّة حبّيتها أكثر من 101 ❤️ ❤️\nبس اختباراتها أصعب شوي 😆\nومو طويلة مثل الـ 101 !\nوالمذاكرة من الكتاب هي أفضل شيء ،\nكتابين اشكر اللي سوّاهم بعنف :\nالكالكولاس + الكمستري ❤️ ❤️ ❤️\n\nchapter 14\nيتكلم عن الـ Chemical Kinetics\n\nchapter 15\nعن الـ Chemical Equilibrium\n\nchapter 16\nAcid Base\n\nونبدأ بالصعوبة من هذا الشابتر 17 :\nACID-BASE EQUILIBRIA\nيبغى له تركيز وححححلّ مسائل كثير !\n\nchapter 18\nSpontaneity, Entropy, and Free Energy\n\nchapter 19\nElectrochemistry\n\nchapter 10\nOrganic Chemistry\nوهو الشابتر المفضّل عندي ❤️ ❤️ 😆\n\nالباقي نسيته 😆 :d", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/chem-102-general-chemistry-ii/120590/3", "user": "user4492", "ts": 1344218684000, "tid": 120590, "pn": 3}}', 1344218684000, 1794766199, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1077404-chem102', 'stk-magical', 'CHEM 102', 'info', '{"desc": "بآلنسسبه ل chem102 آلمآدهـ حلوهـ وأحلآ من 101 ويكفي إنهآ أقل من مآتيريآل 101\n\nمآدهـ يبيلهآ متآبعه وحل أسئلة آلكتآب وزي مآقآل فآلح آلكتآب أهم شي للمذآكرهـ 😊", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/chem-102-general-chemistry-ii/120590/4", "user": "magical", "ts": 1344361557000, "tid": 120590, "pn": 4}}', 1344361557000, 1794766199, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1228581-chem102', 'stk-guest', 'CHEM 102', 'info', '{"desc": "المادة جميلة تقريبا نصفها حسابات كيميائية ونصفها كلام ونظريات\n\nتشابتر 14 سهل بس لازم تحفظ القوانين\nتشابتر 15 سهل وأغلبه عدا علينا في الثانوي (الاتزان الكيميائي)\nتشابتر 16 متوسط مشكلته الطول وتعدد الأفكار ركز هنا على السامبل بروبليمز\nتشابتر 17 صعب ويبغاله شغل محترم عشان تتمكن منه\nتشابتر 18 شكله سهل لكن يلعبوا في أسئلته بشكل كبير ويلعبوا في الاشارات\nتشابتر 19 مباشر الى حد ما اللي في الكتاب هو اللي يجيك بالضبط\nتشابتر 20 متوسط (أنصح بسلايدات السعدي في هذا التشابتر)\nتشابتر21 تشابتر سوالف مدري ليش ناخذه\nتشابتر 22 المفاهيم فيه جديدة ويبغاله حفظ في بعض الجزئيات\nتشابتر 25 نفس 21 تشابتر سوالف\nتشابتر 10 الكيمياء العضوية حسب محبتك لها بيسهل أو يصعب عليك التشابتر", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/chem-102-general-chemistry-ii/120590/5", "user": "Guest", "ts": 1369641739000, "tid": 120590, "pn": 5}}', 1369641739000, 1794766199, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1231850-chem102', 'stk-_716', 'CHEM 102', 'info', '{"desc": "بشكل عام بالنسبة لي المادة أسهل من الـ 101 بس يبغالك تركز على المياجر لأنه بتحدد شيء كبير من القريد النهائي واي تفريط في اي ميجر راح يروح عليك قريد او قريدين على الاقل…\n\nبرضوا الكلاس وورك لازم تشد حيلك في الكويزات", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/chem-102-general-chemistry-ii/120590/6", "user": "_716", "ts": 1370358457000, "tid": 120590, "pn": 6}}', 1370358457000, 1794766199, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1367579-chem102', 'stk-user8581', 'CHEM 102', 'info', '{"desc": "https://www.google.com.sa/url?sa=t&rct=j&q=&esrc=s&source=web&cd=2&ved=0CC4QFjAB&url=http%3A%2F%2Ffaculty.kfupm.edu.sa%2FCHEM%2Fhbadawi%2Fcourses%2Fchem102%2FCHEM%2520102-Syllabus.doc&ei=yXB7U_PkM9Da0QW2v4CQAw&usg=AFQjCNFe-XwVHHimDBBhz0KpNBOUfzgUWw\nهذا سلاباس لسمستر سابق\nبس ترا صار في تغيير في 102 اذا ماني غلطان", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/chem-102-general-chemistry-ii/120590/12", "user": "user8581", "ts": 1400598828000, "tid": 120590, "pn": 12}}', 1400598828000, 1794766199, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1368310-chem102', 'stk-gamofrn', 'CHEM 102', 'info', '{"desc": "http://skfupm.kfupm.edu.sa/vb/showthread.php?t=124372\n\nشكر للأخ كاتب الموضوع\n\nجمع ملفات قيمة لهذا الكورس\n\nبالتوفيق للمقدمين على الكورس\n\nشدوا حيلكم … والكورس سهلات … ويحتاج ماث قليلا في تشابتر 16 + 17 ( الكلكوليشنز غالبا هنا )\n\nوكله ان شاء الله بسيط مع المذاكرة أو بأول\n\nوبشكل عام … أتفق حرفيا مع الأخ أبو خلدون\n\nوتم أضافة اشياء جديدة للكورس مثل البرزنتيشن", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/chem-102-general-chemistry-ii/120590/13", "user": "GAMOFRN", "ts": 1400681722000, "tid": 120590, "pn": 13}}', 1400681722000, 1794766199, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1368864-chem102', 'stk-abu_hamad_22', 'CHEM 102', 'info', '{"desc": "هذا كورس تريكاته أكثر من 101\n\nبس ميزته آقصر و بكل أمانة بتتذوّق حلاوة الكيمستري أكثر من 101 اللي كل آبوه حفظ و غثة\n\nعالعموم ركز على التشباتر الاحماض و القواعد آعتقد 16 و 17 … لآن يلعبون فيها لعب بالمياجر و الفاينل\n\nو بالذات الكيمستري … آي كورس لابُد من المتابعة آول بآول … لآن الكيمستري معروف انه كورس طوييل و يبي لع شغل و فهم من بدري\n\nنظام تفتحه لي ليلة الميجر … لا تحلم بدرجة كويسة\n\nبالتوفيق", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/chem-102-general-chemistry-ii/120590/14", "user": "Abu_Hamad_22", "ts": 1400723517000, "tid": 120590, "pn": 14}}', 1400723517000, 1794766199, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1504275-chem102', 'stk-m7med_21', 'CHEM 102', 'info', '{"desc": "11 شابتر اقل من 101 لكن بالحقيقة المادة اصعب وبفارق من 101\nفيها الفهم وفيها الحفظ بشكل اقل وفيها تنوع مواضيع\nوبصراحة المادة اجمل بكثير من 101\nكل الشابترات مستواها معقولة عدا شابتر 17 محتاج تركيز شوي لتفهم الكونسبيت لكنه ممتع لو فهمته !\nمبرايي هي اصعب مواد الفريشمن بدون منازع والقريد فيها محتاج مجهود محترم", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/chem-102-general-chemistry-ii/120590/17", "user": "M7med_21", "ts": 1546187231000, "tid": 120590, "pn": 17}}', 1546187231000, 1794766199, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1527776-chem102', 'stk-yousef_alamoudi_4507', 'CHEM 102', 'info', '{"desc": "يا سلام على الكورس ذا و الله من امتع الكورسات اللي اخذتها و احلى من 101 بدون كلام و اتوقع الكل يتفق في ذا الشئ، و الله ودي ارجع اخذه مرة ثانية من حلاوته.\n\nطبعا الشباتر فيه اقل من 101 بس اصعب و لكنها ممتعة جدا، و تفصيلها كالاتي :\n\n-شابتر 14 : يتكلم عن شئ اسمه Chemical Kinetics، اشوفه سهل بس فيله حفظ كثير شوي و جزئية الميكنزم انتبه لها شوي.\n-شابتر 15: يعطيك مقدمة للـequillibrium و اللي هو الاتزان الكيميائي لو تتذكره من الثانوي (كيمياء 3)، شابتر خفيف و لطيف و مرة ممتع.\n-شابتر 16: يغطي عن الاحماض و القواعد و يتعمق فيها، يعتبر سهل لكنه دسم مررة و كثير جزئيات فيه.\n-شابتر 17: بكل بساطة دف شابتر 15 و 16 في خلاط و يطلعلك ذا، يعتبر الاصعب و ممكن تلاحظ انه بيجيك احلى ايرور404 لمن تشوفه اول مرة و لكن صدقني مع المقاطع و المراجعة المستمرة بيصير سهل، حاول تحل كثير للشابتر ذا عشان يتركز في مخك و تعرفله.\n-شابتر 18 : شابتر ثيرموداينمكس يعتبر و يتلكم عن الـ entropy and free energy، فيله شوية قوانين بس بسيط و كعادة الثيرموداينمكس اللعب فيها يكون بالاشارات فانتبه كثثثييير و ايضا الوحدات ركز فيها (الجول و الكيلوجول و حتتذكر كلامي).\n-شابتر 19: يبدأ تنوع المواضيع من هنا، يتكلم الشابتر الرهيب ذا عن الـ Electrochemistry، علاقة الكهربا مع الكيمياء و الاشياء ذي، مررررة شابتر رائع و ممتع جدا.\n-شابتر 22: يتلكم عن الـ Coordination Chemistry ، بكل بساطة هو نوع من المركبات لو سمعت بيها ايام الثانوي اللي هي المركبات التناسقية و يتفرع شوي فيها، جددددااااا ممتع و بالنسبة لي اعتبره اخف شابتر هو و 15.\n-شابتر 25: يا حبيبي ذا الشابتر لو انك تعشق الاورجانيك فانك حتعشقها اكثر مع الشابتر ذا، يتلكم عن كيفية تسمية المركبات العضوية بنظام الIUPAC و التفاعلات والمتعلقة بيها، ركز في جزئية التفاعلات ممكن تكون صعبة شوي و تحتاج تركيز و بتصير سهالات ان شاء الله.\nشابتر 20: يتكلم عن الـ Nuclear Chemistry، طبعا شابتر جدا ممتع ولكن فيه شوي مفاهيم حفظ بالذات في اخره (جزئية الانشطار النووي و الاندماج اسئلتها غالبا تكون تعاريف و كذا في الاولد)، ما اشوف فيله شئ صعب للامانة و كان شرح المعلم له مرررة رائع قلب وثائقي يا راجل ما شاء الله XD.\n\nهذا كان تفصيل الشباتر، بالنسبة لطريقة المذاكرة بعد تجربة طريقتين (وحدة قبل الميد و الثانية بعد الميد) فاني ارجح الثانية و هي كالاتي:\n\nبعد المحاضرة اروح اتفرج عل مقطع (اذا حاب او اذا ما فهمت) و بدلكم عل افضل قناتين بالنسبة لي من ايام ال101، و بعدها اروح للوورك شيت (عبارة عن ورقة اسئلة افكارها حلوة و تطبق عليها المفاهيم و ممكن تاخذ بيها نظرة عن التريكات و الشباب ما قصروا حلوا الووركشيتس كلها مع الخطوات و نزلتها على الريسورسز تلاقوها في others_) احلها كلها و بعدها اولد علطول (الدكتور ماهو مقصر حاط تشكيلة حلوة لاسئلة اولد في الووركشيت نفسها) و بس امورك باذن الله في السليم (انا ما اغصبك انك تسوي ذي الطريقة بس ذي اقتراح مني اذا ضايع و ما تعرف اش تسوي، و اذا ما نفعت معاك شوف طريقة ثانية زي انك تراجع جماعي مع اصحابك او…او…)\n\nالقناتين اللي كنت اتفرج عليهم هم ذولي :\n\n+ Organic Chemistry tutor، الاسطورة ذا الانسان اسطورة لا كيمياء و لا ماث و لا حتى فيزيا، ذا اتفرج عليه و انت مغمض، فيديوهاته متعة سمعية اقسم بالله، طبعا اسلوبه يحل مسائل و يعطي شوي كونسبت بسيط لو محتاج الحال.\n+Professor Dave Explains ، ذا ادمي مررة خرافي في الكونسبت متمكن فيه، نظامه يغطي افكار اساسية في مقطع ابو خمس دقايق، لو تعمقت لكيم 201 اتوقع بيكون اسطوري معاك لانه بدايته في اليوتيوب كان يشرح اورجانك عميق شوي.\nو ما يمنع انك تتفرج على غيرهم طبعا اليوتيوب بحر، شوف اللي يناسبك و روح معاه.\n\nطبعا عشان الكورونا و الاونلاين الجامعة قررت انها تلغي نظام المياجر و تجيب نظام الميدات، الميد حق كيم 102 كان وسط صعوبته بس شابتر 18 كان فحل شوي (الشباتر كانت 16و 17 و18).\n\nبالنسبة للفاينل كان الماتريال كامل طبعا بس صعبوته كان وسط حمدلله.\n\nطبعا المادة لازم تذاكرها اول باول ولا لا تحلم بقريد يا عزيزي\n\nنصيحة اخيرة، لو نزلت المادة ذي مع المعلم و كان هو االوحيد اللي يدرسها في الترم فا شد حيلك في الكويزات و حاول تجيب بالقليل 3/4 في كل كوز (ترا مقدور عليها لا تخاف)، و السبب لانه اذا دكتور واحد بس درس المادة ذي في ترم فانه ما راح يكون في نورمالايز لدرجة الكويزات (يعني من الاخر الدرجة اللي بتجيبها بتنزل في القريد لا تنقص و لا تزيد) و هذا راح يساعدك كثيييير في الدرجات و يسهل عليك تجيب قريد محترم.\n\nو اي اسئلة انا في الخدمة… 😄\n\nو الله يوفقكم و فالكم الA+", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/chem-102-general-chemistry-ii/120590/18", "user": "yousef_Alamoudi_4507", "ts": 1610296167000, "tid": 120590, "pn": 18}}', 1610296167000, 1794766199, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-ibrahim_saeed-chem102', 'stk-ibrahim_saeed', 'CHEM 102', 'doc', '{"docs": [{"id": "stk-dr-f68452", "n": "Dr. Hasan Al-Muallem", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "درست عند المعلم chem 102\n\nالتحضير : يوميا ورقة تمر على الشعب\nطريقة الشرح : بالنسبة للترم ذا كان المعلم ضايع\nكان يوم سلايدات و يوم سبورة\nالقريد : c\n\nالزبدة\nالاستاذ طيب و أخلاق لكن لا تفكر تاخذ معه 102 لو ايش\nخذ معه 101 أو 201 بس", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1228599-chem102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/hasan-al-muallem/68452/35", "user": "IBRAHIM_SAEED", "ts": 1369646459000, "tid": 68452, "pn": 35}}]}', 1369646459000, 1794766199, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-medoalkebsi-chem102', 'stk-medoalkebsi', 'CHEM 102', 'doc', '{"docs": [{"id": "stk-dr-f68452", "n": "Dr. Hasan Al-Muallem", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "كمستري 102 ترم 132\n\nالتحضير : يمرر ورقه كل يوم بدايه الكلاس\nطريقة الشرح :يشرح من السلايدات حق السعدي\nالكويزات : اختيارات ومستواها مثل المياجر\nالمياجر:كومون\nالفاينلات :كومون بس باقي ما اختبرنا 😆\nالقريد النهائي: اعطيه كقريد نهائي A للدكتور\nالصوت: واضح جدآ\nإضافات : المدرس متساهل وحبيب , ماشاء الله عليه يحفظ الطلاب كلهم .\nالمدرس كثيييير مفيد في الرستيشن .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1350534-chem102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/hasan-al-muallem/68452/39", "user": "Medoalkebsi", "ts": 1397120275000, "tid": 68452, "pn": 39}}, {"id": "stk-dr-f68544", "n": "Dr. M.b. Fettouhi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "نزلت معه سمستر 122 بعدين سويت دروب كامل .\n\nوالله ياكنا نكرف كرف الحمير , وبالاخير نص الي سيويناه غلط , الكلام هذا كمستري 102\n\nكنا نقعد من الساعه 1 الظهر الين بعد 5\n\nمره ارسل لنا رساله قال تعالوآ من 12 عشان تقدروآ تخلصوآ الساعه 5 وتلحقوآ ع الاختبار الساعه 6.30 .\n\nابدا ابدا ابدا ما انصح تنزل معه لاب", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1353164-chem102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/m-b-fettouhi/68544/17", "user": "Medoalkebsi", "ts": 1397684284000, "tid": 68544, "pn": 17}}]}', 1397120275000, 1794766199, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-ieren-chem102', 'stk-ieren', 'CHEM 102', 'doc', '{"docs": [{"id": "stk-dr-f68452", "n": "Dr. Hasan Al-Muallem", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "كمستري 102 \\132\nالتحضير ورقة تمر على الكل تقدر تحضر خويك طبعا ولا يدقق\nالكويزات اصعب من المياجر بكثيييييييييييير\nالهوموركات يعطي من الكتاب واذا شاف الشعب ينسخ من المانوال سليوشن يعطي اسئلة من عنده وصعبة بعد\nاشرح من سلايدات السعدي حلوو وصوته ما يوصل الى اخر الكلاس\nالقريد النهائي b", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1362197-chem102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/hasan-al-muallem/68452/40", "user": "iEreN", "ts": 1399456403000, "tid": 68452, "pn": 40}}]}', 1399456403000, 1794766199, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abu_hamad_22-chem102', 'stk-abu_hamad_22', 'CHEM 102', 'doc', '{"docs": [{"id": "stk-dr-f118605", "n": "أ. عبد الله الأحمدي", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Lab Chem 102 --- Term 132\nالتحضير :\n\nعن طريق الريبورت\nطريقة الشرح :\n\nجداً ممتازة و سلسة … يشرحها و الخطوات مكتوبة بالسبورة و عادي تسآله\nالكويزات :\n\nطول السمستر ما خذنا البري لاب يا لبى قلبه\nالمياجر:\n\nما في\nالفاينلات :\n\nحدد آربع تجارب لـ الجزء الكتابي … و وحدة للجزء العملي … جداً سهل\nالقريد النهائي: A+++++++++++++++++++++\nالصوت:\nجداً وااضح و مسموع و مفهوم\nإضافات :\n\nأنا أنصحك و بشدة تنزل عند هذا الرجل الفاضل\n\nحبيب و شبابي و راعي سوالف … و عادي وقت أنتظار التجربة تتكي و تسولف معه و كذاا\n\nو ياخذ و يعطي …\n\nلو يحصل لي لاب بالمستقبل … بلا تردد راح آختار هذا الانسان الفاضل", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1358221-chem102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/118605/16", "user": "Abu_Hamad_22", "ts": 1398606012000, "tid": 118605, "pn": 16}}, {"id": "stk-dr-f68452", "n": "Dr. Hasan Al-Muallem", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Chem 102 ---- Term 132\n\nالتحضير :\n\nورقة تمر على الكلاس\n\nطريقة الشرح :\n\nسلايدات السعدي و المسائل يحلها بالسبورة بخطوات واضحة … بس بشكل عام الوضع مُمل\n\nالكويزات :\n\nالصراحة إذا ما ذاكرت كويّس أنسَ تحل الكويزات … عبارة عن 4 آسئلة و 4 اختيارات … إذا حظك حلو بيضبط guess معك …\n\nالمياجر:\n\nصعبة جداً جداً جداً … للآسف في ظاهره السؤال حليو لكن ملغم تريكات و تروح عليك :sneezing_face: 😞\n\nالفاينلات :\n\nما بعد نختبر فاينل\n\nالقريد النهائي:\nC+\n\nالصوت:\n\nعادي و على نبرة وحدة طول الكلاس\n\nإضافات :\nانا اشوف عادي نزّل معه … بس الكيمستري بشكل عام يبي له متابعة أول بأول … يعني الدكتور يكون مؤثر … بس مو كثيير", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1365105-chem102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/hasan-al-muallem/68452/41", "user": "Abu_Hamad_22", "ts": 1400179553000, "tid": 68452, "pn": 41}}]}', 1398606012000, 1794766199, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-hellblizzard-chem102', 'stk-hellblizzard', 'CHEM 102', 'doc', '{"docs": [{"id": "stk-dr-f68452", "n": "Dr. Hasan Al-Muallem", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Chem 102\n\nالتحضير : ورقة تحضير تمر على الطلاب\nطريقة الشرح : شرح ممتاز. يشرح على سلايدات و يكتب على السبورة. يحب يسأل الطلاب في وسط الشرح عشان ياخذ اراءهم.\nالكويزات : اختيارات. متوسطة. يرفع على البلاكبورد واجبات اختيارية تحلها للمذاكرة فقط و يجي منها سؤال او اثنين في الكويز نسخ لصق\nالمياجر:كومن\nالفاينلات : كومن\nالقريد النهائي: A+\nالصوت: واضح\nإضافات : من أفضل الدكاترة اللي مرو علي بالجامعة. نزل عنده بدون تردد و ما راح تندم. 👍", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1473954-chem102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/hasan-al-muallem/68452/47", "user": "HellBlizzard", "ts": 1495971470000, "tid": 68452, "pn": 47}}]}', 1495971470000, 1794766199, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-m_shaer6-chem102', 'stk-m_shaer6', 'CHEM 102', 'doc', '{"docs": [{"id": "stk-dr-f68452", "n": "Dr. Hasan Al-Muallem", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "بنود التقييم :\nCHEM102 …\n\nالتحضير :\nتحضير يومي … ورقة تمر ع الطلاب ويوقعوا … ويحفظ الطلاب بسررررعه …\nيتضايق من التأخير بس ما يحاسب عليه اتوقع …\n\nطريقة الشرح :\nيشرح من سلايدات السعدي و يكتب ع السبوره … شرحه حلو …\n\nالكويزات :\nناااار غالباً … مستواها شخصياً شفته صعب صراحه …\n4 اسئلة اختياري … كل سؤال عليه 2.5 ومايهتم للحل … اهم شي الجواب الي تختاره …\n\nالمياجر:\nكومن … كان هو الكوردنيتر وكانت ناااااااااااااار … الأفرج كان بين ال50 و ال60 …\n\nالفاينلات :\nنفس كلام المياجر …\n\nالصوت:\nواضح ومفهوم … ماعليه ملاحظات …\n\nإضافات :\nطبعاً كل اسبوع كوز في الريسايتشين … ولو ما كان فيه كوز ما يحضر …\nو الكلاس تحسه طويل مرررررررررره …\nطبعاً اخلاق الدكتور … طيب جداً …", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1473994-chem102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/hasan-al-muallem/68452/48", "user": "m_shaer6", "ts": 1495991302000, "tid": 68452, "pn": 48}}]}', 1495991302000, 1794766199, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-adg2015-chem102', 'stk-adg2015', 'CHEM 102', 'doc', '{"docs": [{"id": "stk-dr-f68452", "n": "Dr. Hasan Al-Muallem", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CHEM 102 - 162\n\nالتحضير :\nورقه وتمشي عالطلاب وما يشيك عليها\nطريقة الشرح :\nمن السلايدات , شرحه اسطوري ويجاوب على اسئلة الطلاب بشكل مفهوم\nالكويزات :\nناااار بمعنى الكلمة لازم تذاكر زين وغالبا يجيب بعض الأسئلة من كويزاته القديمه واسئلة الرسيتيشن\nالمياجر:\nنااار وما يرحم , بس الميجر الثاني كان اسهل شوي\nالفاينلات :\n😞\nالقريد النهائي:\nA\nالصوت:\nواضح\nإضافات :\nالدكتور شريح واخلاقه عاليه ومتعاون جدا حاول تستفيد من شرحه في الكلاس\nالكونسبت في Chem 102 سهل وممتع بس الاختبارات دائما تكون سبرااايز\nومع المعلم كان الوضع اكشن مرره", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1474198-chem102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/hasan-al-muallem/68452/49", "user": "Adg2015", "ts": 1496180569000, "tid": 68452, "pn": 49}}]}', 1496180569000, 1794766199, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-breaktheunbreakable-chem102', 'stk-breaktheunbreakable', 'CHEM 102', 'doc', '{"docs": [{"id": "stk-dr-f68452", "n": "Dr. Hasan Al-Muallem", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CHEM 102 - 162\n\nالتحضير :\nورقة تمر. ما يهم لو تتأخر.\nطريقة الشرح :\nسلايدات والسبورة ويتعاون مع الطلاب. شرحه يجيب النوم\nالكويزات :\nصعبة\nالمياجر:\nصعبة جدا\nالفاينلات :\nصعب\nالقريد النهائي:\nC+\nالصوت:\nواضح\n\nالله يعين الطلاب على ذي المادة اللي أصعب من الفزكس والماث 😃", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1492299-chem102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/hasan-al-muallem/68452/52", "user": "BreakTheUnbreakable", "ts": 1526268779000, "tid": 68452, "pn": 52}}]}', 1526268779000, 1794766199, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-m7med_21-chem102', 'stk-m7med_21', 'CHEM 102', 'doc', '{"docs": [{"id": "stk-dr-f68452", "n": "Dr. Hasan Al-Muallem", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Chem 102 - 181\n\nالتحضير : ورقة تمر على جميع الطلاب عادي تخلي حد يحضرك او تتاخر ما بيتكلم بس لا تفلها يعني يحفظ اسامي الطلاب بسرعة\nطريقة الشرح : من سلايدات السعدي يرفعها اول باول ممتازة جدا السلايدات صراحة وقد تغني عن الكتاب … شرحه جدا ممتاز يستخدم السبورة احيانا عند الاحتياج ويتجاوب ويحب يتفاعل معه الطلاب\nالكويزات : صعبة جدا صراحة … روح مستعد لها كانك مستعد لميجر الكويزات عليها 17.5 فانتبه تفرق معك ولا تفرط\nرح يحذف اسوء كويز او كوزين بالنهاية\nالياجر : صعبة\nالفاينل : اسهل من المياجر\nالقريد النهائي : A+\nاضافات:\nالله يوفقه الدكتور المعلم محترم جدا وبشوش واخلاق توب توب\nطريقته كل شابتر كويز وهومورك … حاول تحل الهومورك بنفسك مستواه كويس للدراسة والكويز ادخل كانك ميجر", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1504274-chem102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/hasan-al-muallem/68452/53", "user": "M7med_21", "ts": 1546187094000, "tid": 68452, "pn": 53}}]}', 1546187094000, 1794766199, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abdulrahman_alghamdi-chem102', 'stk-abdulrahman_alghamdi', 'CHEM 102', 'doc', '{"docs": [{"id": "stk-dr-f68452", "n": "Dr. Hasan Al-Muallem", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CHEM102-182\n\nالتحضير : يوزع ورقة بداية الكلاس وما يتأكد من الحضور. يتضايق جدًا من المتأخرين واللي يحضرون اصحابهم، لكن إلى الآن ما شفته سوا شي بخصوص الموضوع هذا.\n\nطريقة الشرح : بطلة باختصار. يستخدم سلايدات السعدي ويشرحها بشكل واضح ومفهوم. يرمي لنا كم سؤال عشان جو الحصة ما يكون نايم. ويعطينا بعض التلميحات للتريكات الي تجي في المياجر.\n\nالكويزات : متوسطة الى صعبة. 4 أسئلة اختيارات كل سؤال عليه 2.5، الترم هذا اختبرنا 8 كويزات وحذف أسوأ واحد\n\nالمياجر: كومن (بس نار)\n\nالفاينلات : كومن\n\nالقريد النهائي: ِA+ بجدارة\n\nالصوت: واضح وانجليزية ممتازة.\n\nإضافات : من أحسن الدكاترة الي درست عندهم إلى الآن. دائمًا يحرجك بأخلاقه وطيبته. أكثر من مرة نطلبه يلغي كلاس ريسايتيشن، يلغيه بدون نقاش.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1508792-chem102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/hasan-al-muallem/68452/54", "user": "Abdulrahman_Alghamdi", "ts": 1555761572000, "tid": 68452, "pn": 54}}, {"id": "stk-dr-f176823", "n": "Dr. Jalilov Almaz", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CHEM 102-182- LAB\n\nالتحضير : لاب. يحضر بالريبورت والكويز\n\nطريقة الشرح : الدكتور أحسه يكره كورس 102 بشكل مو طبيعي، أكثر من مرة يقول ان لاب 201 أحسن بكثير. عمومًا هو يحاول يوصل فكرة اللاب بأبسط صورة ويحاول انه يقلل الشغل\n\nالكويزات : أسهل ما يكون، 3 أسئلة اختيارات تجي من المنهج (مو من المانوال)\n\nالفاينلات : العملي كومن. النظري نفس نظام الكويزات، الفرق انه 15 سؤال بدل 3\n\nالقريد النهائي: B+\n\nالصوت: لهجة روسية تطرب، الصوت نوعًا ما غير مسموع، نطق بعض الكلمات يجيب الجلطة.\n\nإضافات: اذا انت راعي فهم خاصة في 102 ما اتوقع انه الخيار المناسب لك. أما إذا كنت من الناس اللي يبغون يخرجون من ثاني ساعة، فالدكتور متخصص في هذا الشي. الدكتور طيب جدًا وهذا شي ما أنكره، لكن في المقابل ماهو الخيار الأنسب لفهم اللاب. تصحيح الدكتور عبارة عن تسليك، كل ريبورتاتي اخذت فيها فوق ال45 من 50", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1508793-chem102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/jalilov-almaz/176823/5", "user": "Abdulrahman_Alghamdi", "ts": 1555762004000, "tid": 176823, "pn": 5}}]}', 1555761572000, 1794766199, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user11325-chem102', 'stk-user11325', 'CHEM 102', 'doc', '{"docs": [{"id": "stk-dr-f68452", "n": "Dr. Hasan Al-Muallem", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Chem 102 ---- Term 192\n\nالتحضير :\n\nورقة تمر على الكلاس\n\nطريقة الشرح :\n\nسلايدات السعدي و المسائل يحلها بالسبورة بخطوات واضحة\nوبنهاية السمستر يعرض على الطلاب انهم يسووا برزنتيشن مقابل يحذف اسوأ كويز و هوموورك ، فكرة حلوة\n\nالكويزات :\n\nهمممم بصراحة 4 اسئلة خيارات اذا ماذاكرت بتجيب 0-2.5\nاذا مذاكرتك هه هه هه 5-7.5\nاذا ذاكرت زين 10\n\nالمياجر:\n\nمياجره من بعيد تشوفها سهلة وش حلوة بعدين تنصدم من درجاتك اللي نقصتها يعني من الاخر ملغمة\n\nالفاينلات :\n\nههههه صعبة الافرج 52 زي المياجر\n\nالقريد النهائي:\nB\n\nالصوت:\n\nكويسة وعنده منبه لنهاية الكلاس يقول تحبونها خخخخخخخ\n\nإضافات :\nالدكتور حبيب ويحفظ اسمك حتى لو ماعمرك كلمته ، المهم انصح فيه وانا بنزل معه اورقانك ابي راوند 2 😠 🥊", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1518371-chem102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/hasan-al-muallem/68452/55", "user": "user11325", "ts": 1577433500000, "tid": 68452, "pn": 55}}]}', 1577433500000, 1794766199, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-terox-chem102', 'stk-terox', 'CHEM 102', 'doc', '{"docs": [{"id": "stk-dr-f68452", "n": "Dr. Hasan Al-Muallem", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Chem 102 Lec / 192\n\nالتحضير: ورقة تمر عليك وتكتب اسمك باللغة العربية. يسمح بالتأخير بشكل عام لكن بيكلمك ويقولك ليه تأخرت\n\nطريقة الشرح: يشرح من سلايدات السعدي وشرحه جدا ممتاز + يحل كم سؤال\n\nالكويزات : اخذنا الكويزات عند دكتور شريف وكانت جدا سهلة ولكن اخر الترم المعلم عطانا 3 كلاس تيست على البلاك بورد وكان مستواهم متوسط الى صعب\n\nالمياجر: كومن\n\nالفاينلات : كومن\n\nالقريد النهائي: +A\n\nالصوت: واضح جدا والاكسنت ممتاز ويسمح لك تكلمه عربي\n\nإضافات : الدكتور عسل الله يحفظه وكمية اخلاق ومتساعد بشكل كبير باختصار سجل عنده وما بتندم", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1521892-chem102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/hasan-al-muallem/68452/56", "user": "Terox", "ts": 1589055959000, "tid": 68452, "pn": 56}}]}', 1589055959000, 1794766199, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-yousef_alamoudi_4507-chem102', 'stk-yousef_alamoudi_4507', 'CHEM 102', 'doc', '{"docs": [{"id": "stk-dr-f68452", "n": "Dr. Hasan Al-Muallem", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CHEM102- term 201\n\nالمعلم و ما ادراك ما المعلم يا حبيبي\n\nالتحضير: ياخذ التحضير من التيمز بدون ما ينادي اسماء اذا جيت خلال اول 5 دقايق ما اتوقع يعطيك غياب.\nطريقة الشرح: سلايدات السعدي و يحل كم سؤال عشان الفهم، شرحه لا يعلى عليه جداااا ممتاز ما عليك، حرفيا بذمة و ضمير يشرح.\nالكوزات: كل شابتر و له كويزه ما عدا شابترين (25و22 اذا ما خاب ظني)، 4 اسئلة خلال ثلث ساعة، الصعوبة وسط ما عدا سؤال واحد فيه تريك اليم، الكويزات طبعا عالبلاك.\nالميد: كومن\nالفاينل: كومن\nالقريد النهائي: و الله A+ قليلة بحقه.\nالصوت: واضح ما يحتاج و يسمحلك تتكلم بالعربي ما عندك اشكال.\nاضافات: الدكتور جددددااا متعاون بشكل خيالي لدرجة انه عمل لنا حصة ليلية مراجعة اسئلة و حل و من ذا الكلام وقت الكلاس تست الثاني، و قعدنا ساعتين فصفصنا اهله ياشيخ XD\nحبوب و يحب يمزح شويات، من الاخر نزل معاه و انت مغمض\nكيم 102 احجزها عنده دايم.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527769-chem102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/hasan-al-muallem/68452/58", "user": "yousef_Alamoudi_4507", "ts": 1610293089000, "tid": 68452, "pn": 58}}]}', 1610293089000, 1794766199, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-k.q-chem102', 'stk-k.q', 'CHEM 102', 'doc', '{"docs": [{"id": "stk-dr-f68452", "n": "Dr. Hasan Al-Muallem", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CHEM 102 - Term 202\n\nالتحضير: عن طريق الشيت من تيمز فقط.\n\nطريقة الشرح: شرحه جيد جدا. يشرح عن طريق سلايدات السعدي ويضرب امثلة توضح الفكرة ويربط المادة مع الحياة.\n\nالكويزات: كل تشابتر عليه كوز خيارات ٤ اسئلة. يحذف أسوأ كويز نهاية التيرم. مستواها متوسطة الى صعبة اذا بتذاكر السلايدات بس. اما اذا بتذاكر الوورك شيت حقت الدكتور بتكون سهلة ان شاء الله.\n\nالمياجر: كومن.\n\nالفاينالز: كومن.\n\nالقريد النهائي: +A.\n\nالصوت: واضح والاكسنت ممتاز.\n\nاضافات: الدكتور انصح فيه وبقوة. اخلاق عالية تدرس ومتعاون بشكل كبييير مع الطلاب. اساله في اي وقت عبر الايميل وبرد عليك. متعاون في اختيار اوقات الكوزات.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1529534-chem102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/hasan-al-muallem/68452/59", "user": "K.Q", "ts": 1618771263000, "tid": 68452, "pn": 59}}]}', 1618771263000, 1794766199, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user6010-chem102', 'stk-user6010', 'CHEM 102', 'doc', '{"docs": [{"id": "stk-dr-f68455", "n": "Dr. K Alhooshani", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "السلام عليكم ورحمة الله وبركااته\n\nانا حاب اعطيكم تجربتي مع الدكتور خالد الحوشاني,\nاولا : انا ادرس معاه السميستر هذا101 chem102 واشوفه افضل مدرس مر علي من جيت الجامعه لانه فاهم المنهج وطريقة شرحه ممتعه وما يعدي نقطه إلا وانت فاهمه ومتسااااعد جدااا مع الطلاب ومحترم .\nصوته في المحاضره ممتاز.\nكويزاته سهله الى متوسطه.\nالتحضير بعد 10 دقايق ممكن يسجلك غايب واحيانا ما يدقق.\nيساعد الطلاب باللي يقدر عليه من هلب سشن وغيرها\n\nان شاء الله اكون افدتكم بشي", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p745576-chem102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/k-alhooshani/68455/13", "user": "user6010", "ts": 1292572359000, "tid": 68455, "pn": 13}}]}', 1292572359000, 1794766199, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-ant_s_brain-chem102', 'stk-ant_s_brain', 'CHEM 102', 'doc', '{"docs": [{"id": "stk-dr-f68455", "n": "Dr. K Alhooshani", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "تقييم\n\nK ALHOOSHANI\n\nالتحضير: يومياً بورقة تمر وتوقع عند اسمك ،،، وبعض الأحيان يعد عدد الحاضرين وعدد الموقعين ليختبر أمانة طلابه في التحضير ،،، وإذا لاحظ عدد الموقعين زايد على عدد الطلاب\n<يزعل ويطرطع وياويلك أنت وخويك الغايب اللي حضرته>\n\nطريقة الشرح: رائعة جداً ، سلايدات وشرح بطل وأسئلة (Examples) تحلها في الكلاس سهلة وبسيطة وتحس أنك فاهم لما تحلها ، وفي حصة الريسايتيشن (CHEM 102) يوزع طلابه إلى مجموعات (((وهذا أحلى شيء فيه))) وكل مجموعة تحل كم سؤال جايبها من الأولد إكزامز ، وفي آخر السنة في بونص لأفضل مجموعة تشتغل معاه ويسوي help session قبل المياجر والفاينال وتحلون أولد إكزام كامل ويقسمكم مجموعات زي الريسايتيشن بالضبط\n\nالكويزات: متوسطة تميل إلى السهولة ، (لأني كنت أفهم من اللكشر)\n\nالمياجر والفاينالات: COMMON\n\nالقريد النهائي: +A\n\nالصوت: واضح والآكسنت تبعه بطل\n\nإضافات: بصراحة المدرس ما يتفوت ودايم هو أفضل الدكاترة اللي ينزلون هذا الكورس (CHEM 102)", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p950075-chem102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/k-alhooshani/68455/15", "user": "ant_s_brain", "ts": 1324312120000, "tid": 68455, "pn": 15}}]}', 1324312120000, 1794766199, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user4492-chem102', 'stk-user4492', 'CHEM 102', 'doc', '{"docs": [{"id": "stk-dr-f68455", "n": "Dr. K Alhooshani", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "الدكتور الحوشاني > CHEM 102\n\nشررررح نوعاً ما جيّد إلى ممتاز ،\nومرررة يكون كويّس وتفهم كل شيء ، ومرة لأ 😆\n\nمتعاون واخلاقه عاليه ،\nفي التحضير شدييييد جدّاً ،\nفيه كم طالب وقعوا عن أخوياهم وحضّر بالأسماء واللي غايبين عطاهم 0 في الحضور 😆\n\nكوزاته صعبة وتصير سهله بعد ميجر 2 ،\nفي حصص الريسايتيشن يسوّي قروبات واللي يجمّع أكثر نقاط له بونص …\nبس في النهاية للأسف ماعرفنا من الفايز ولا شفنا بونص …\nيمكن إنه انشغل بمؤتمرات وإجتماعات ونسى هالشغلةة ,\n\nفي اسئلة المياجر ، فيه تخبّط كبيييير …\nو لازم يصير فيه خطأ ويكنسل السؤال وكذلك في الفاينل …\n\nأفضل من درسني كمستري كَ شرح وليس كَ كلاس وورك 😆\n\nالتقييم : B+", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1047903-chem102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/k-alhooshani/68455/16", "user": "user4492", "ts": 1338365911000, "tid": 68455, "pn": 16}}]}', 1338365911000, 1794766199, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user7646-chem102', 'stk-user7646', 'CHEM 102', 'doc', '{"docs": [{"id": "stk-dr-f68455", "n": "Dr. K Alhooshani", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "بسم الله الرحمن الرحيم … درست عند الدكتور كيمستري 102 … ترم 121 تقريبا او 112 …\nالدكتور خلوووووق جدا ومجتهد في ايصال المعلومة بطرق مبتكرة ( خاصة في الريسيتيشن , قروبات و كذا 🙂 )\n\nالتحضير :التحضير كان عن طريق ورقة … نصيحة لا تحضر زميلك … لانه عادي عنده يوقف كل شي و يحقق في المشكلة\n\nطريقة الشرح :يشرح في الكلاس عن طريق السلايدات ( مثل اغلب مدرسين الكيمستري ) … و في الريسيتيشن … قروبات و نظام تنافسي حلو و مفيد … 👍\n\nالكويزات :تقريبا متوسط كان مستواها\n\nالمياجر:طبعا كومون … مستواها متوسسط … ويرسلك درجتك و ترتيبك في سلم الدرجات مقارنة بالطلاب اللي معاك ع الايميل ( عشان تعرف مستواك مقارنة بزملاءك )\n\nالفاينلات :المادة تقريبا طويلة … والفاينل كان شامل … ما افتكر تفاصيله … لكن ما اذكر انه كان صعب جدا او سهل جدا 🤪\n\nالقريد النهائي:خلوق المدرس … شرحه فوق المتوسط و مجتهد … اعطيه B+\n\nالصوت:واضح جدا …\n\nإضافات : مدرس خلوق و تعامله ممتاز مع الطلاب ❤️\nشرحه فوق المتوسط … ومجتهد 👍\n\nبالتوفيق للجميع", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1406540-chem102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/k-alhooshani/68455/28", "user": "user7646", "ts": 1413874381000, "tid": 68455, "pn": 28}}]}', 1413874381000, 1794766199, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user9921-chem102', 'stk-user9921', 'CHEM 102', 'doc', '{"docs": [{"id": "stk-dr-f68455", "n": "Dr. K Alhooshani", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Chem 102 term 151التحضير :\nطريقة الشرح : سلايدات ويشرح عليها وأحياناً يطلب من الطلاب يشوفوا فيديوات عن الدرس قبل المحاضرة ويحلوا واجبات عليها\nالكويزات : وسط وتميل أحياناً انها تكون صعبة\nالمياجر: صعبه شوي (الأفرج الاول 55 والافرج الثاني 50 )\nالفاينلات : كومن\nالقريد النهائي: B\nالصوت: واضح جداً\nإضافات : الدكتور شرّيييح ما عليه كلام بس أسئلته في الكويزات والمياجر تميل للصعوبة", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1434617-chem102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/k-alhooshani/68455/29", "user": "user9921", "ts": 1448545162000, "tid": 68455, "pn": 29}}]}', 1448545162000, 1794766199, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user10520-chem102', 'stk-user10520', 'CHEM 102', 'doc', '{"docs": [{"id": "stk-dr-f68455", "n": "Dr. K Alhooshani", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "التحضير : ورقة تمشي بين الطلاب\nطريقة الشرح : يبدو انه كل ترم له طريقة في الشرح، أنا أدرس عنده الآن كيميستري 102 ، ترم 151 …\nطريقته / يرسل فيديوهات تشرح الدرس -لازم- تشوفها قبل المحاضرة، وفي المحاضرة -باعتبار انك فاهم- يكون فيه حل أسئلة مباشرة وإذا عندك مشكلة في الكونسبت اسأل ويشرح للكل.\nووقت المياجر يرجع للطريقة العادية في الشرح.\n\n+ ما أعتبره شرّيح، يسوّي كل اللي يقدر عليه لكن الكونسبت ماتوصل 100% …\n\nالكويزات : 5أسئلة ، أسئلة مياجر… وقرين شيت بعد.\nالمياجر: تلخبط شوي 😕\nالفاينلات : باقي مااختبرنا\nالقريد النهائي:\nالصوت: واضح، لهجة انجليزية قصيمية 🙂\nإضافات : يحب الأسئلة، يحب الأسئلة، يهتم كثير بالطلاب ويحاول ياخذ رايهم بطريقة الشرح حقته.\nطريقته فيها بعض العيوب، إذا نزّلت عنده تحلطم على سلبياتها… واذا ما فهمت انشب.\n\nبشكل عام ، ممتاز جداً\nوطبيعة الكيميستري، لازم تذاكر بنفسك.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1434729-chem102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/k-alhooshani/68455/30", "user": "user10520", "ts": 1448650101000, "tid": 68455, "pn": 30}}, {"id": "stk-dr-f118612", "n": "أ. عبد الغفار محمد", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "بسم الله\n\nترم 151 - لاب CHEM102\n\nطريقة الشرح :\nيشرح خطوات التجربة بالتفصيييل، هو ممتاز جداً من هذي الناحية، يشرح بالعربي وبالانجليزي،\nويحب الأسئلة ويجاوب عليها…\nاللهجة سودانية جميلة 🙂\nويهتم لفهم الطلاب بشكل كبير.\n\nطريقة كتابة الريبورت :\nكل اثنين في فريق يكتبون الريبورت ويسوون كل شيء مع بعض.\nفي بعض اللابات قال الحسابات في الريبورت فردية وممنوع انك تسأل زميلك… لكن عادي أغلب الحسابات يكون كاتبها بالسبورة.\n\nالبري لاب :\nكل أسبوع تقريباً، تجربة كانت طويلة جداً فألغى البري لاب، وفي أسبوع الميجر ألغى واحد ثاني.\nالأسئلة من البري لاب اللي في الكتاب، ماعنده مشكلة تحله كامل في البيت قبل ما تجي …\nأحياناً يختار الأسئلة الصعبة بعناية، وتصحيحه شديد.\n\nالفاينلات :\nالفاينل لاب الكتابي، كان 7 أسئلة… 6 منها explain.\nوتصحيحه على كل صغيرة وكبيرة.\n+ يركّز بزيادة على بعض النقاط، حددها لأن احتمال كبير يجيبها بالفاينل.\n\nالقريد النهائي:\n\nA+\n\nالصوت:\nواضح، لهجة سودانية جميلة\n\nإضافات :\nيدقق بشدة بالتصحيح، يمكن يكرّهك باللاب. هههههه\nلكنه فعلاً مدرس لاب رهيب، يهتم بكل شيء تقريباً، ما تحس انك قاعد ترمي أرقام وكلمات بالريبورت بس.\n\nوطبعاً بعد ما تشوف الدرجات بعد النورملازيشن تنقهر،، لكن أهم شي العلم. هههههه\n\nيبدو انه آخر سمستر له 😦\nالله يسعده", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1435186-chem102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/118612/11", "user": "user10520", "ts": 1449077148000, "tid": 118612, "pn": 11}}]}', 1448650101000, 1794766199, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user10218-chem102', 'stk-user10218', 'CHEM 102', 'doc', '{"docs": [{"id": "stk-dr-f68455", "n": "Dr. K Alhooshani", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Chem 102 T-142\n\nالتحضير:\n\nورقه تدور\n\nبعض الاحيان ينسى ويأخرك على المحاضره الثانيه\n\nطريقة الشرح :\n\nيشرح من سلايدات السعدي\n\nشرح عادي\n\nالكويزات :\n\nاختيارت متوسطه الى صعبه جدا\nممكن يجيب فيها اسئلة من اختبارات قديمة\n\nيعطيك ورقة الايجابات الخضراء = تصحيح آلي\n\nالمياجر:\nميجرين كومن\n\nالفاينلات :\n\nكومن\nالقريد النهائي:\n\nc+\nالصوت:\n\nواضح\nإضافات :\n\n* الرجال ما يعرف شيء اسمه نهاية الكلاس و دئما ياخذ وقت زياده وبعض الاوقات يتاخر حول 5 دقايق او اكثر\n\nكلاسنا كان بعده بريك الغدا والنتيجيه ما نطلع الا متأخرين اوقات توصل الى ثلث ساعه 😠\n\n* بعد كل ميجر يعطيك واجب انك تحل الميجر وتسلمه\n\n*الريسايتيشن عباره عن كويز و بعدين تحل الكويز مع مجموعتك = كلاس ضايع\nواذا ما في كويز يكون حل اسئله مع مجموعتك\n\n* اوقات يجي وهو ما حضر الدرس تحسه ضايع\n\n*في المقرر مطلوب تقديم عرض\n\nيطلب منك واحد مع مجموعتك واحد لحالك (تسجيل فيديو)\n\nما انصح به 😞", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1437965-chem102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/k-alhooshani/68455/31", "user": "user10218", "ts": 1451889265000, "tid": 68455, "pn": 31}}]}', 1451889265000, 1794766199, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-faisal70-chem102', 'stk-faisal70', 'CHEM 102', 'doc', '{"docs": [{"id": "stk-dr-f68455", "n": "Dr. K Alhooshani", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CHEM102-171\nالتحضير :\nورقة تمر على الطلاب ماشيك عليها الا مرة واحدة.\nطريقة الشرح :\nفي البداية كان مقسمنا لمجموعات و كان يقل لنا حضروا للدرس قبل مانجي المحاضرة و في وقت المحاضرة يعطينا اوراق و كل مجموعة تشتغل عليها. بعد الميجر الاول غير الطريقة بعد ما شاف الافرج نازل فبدا يشرح بنفسه و كان شرحه جيد .\nيشرح من سلايدات السعدي .\nالكويزات :\nالكويزات سهلة\nالمياجر:\nكان يدرس الكورس بلحاله و المياجر متوسطة الصعوبة\nالفاينلات :\nكان سهل\nالقريد النهائي:\nاعطيه B\nالصوت:\nواضح\nإضافات :\nالدكتور مهتم بالعمل الجماعي كثير في الريسيتايشن بعد ماينتهي الكويز تبدا انت و مجموعتك بحل الكويز من جديد و بصراحة ما استفدت منها و كانت مملة .\nعطانا حول الخمس واجبات ثنتين منهم تحل الميجر من جديد .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1486171-chem102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/k-alhooshani/68455/37", "user": "Faisal70", "ts": 1516105731000, "tid": 68455, "pn": 37}}]}', 1516105731000, 1794766199, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abdullah-o-chem102', 'stk-abdullah-o', 'CHEM 102', 'doc', '{"docs": [{"id": "stk-dr-f68455", "n": "Dr. K Alhooshani", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "خالد الحوشاني تشيرمن الكمستري\nCHEM102 - 221\n\nالشرح: على سلايدات السعدي ( منسوخه من الكتاب)، شرحه تفاعلي ويخلي الكل يشارك ويسأل الكل، وشرحه يعطيك الزبده بدون لف ودوران، صراحه ماتطلع من عنده الا وانت مايحتاج تراجع السلايدات بشكل كبير ( الي مايحب يشارك او يحب الماده سلف ستدي او مايركز في المحاضره ما راح يناسبك كثير الدكتور)\n\nالتعامل: الدكتور طيب ويقبل الاسئلة\n\nالتحضير: ورقه تدور في الكلاس، بعض المرات يشيك اذا في احد حضر احد ثاني\n\nفاينل مياجر: كومن\n\nتقييم: A", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1536168-chem102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/k-alhooshani/68455/39", "user": "Abdullah-o", "ts": 1673710061000, "tid": 68455, "pn": 39}}]}', 1673710061000, 1794766199, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-hsn3d-chem102', 'stk-hsn3d', 'CHEM 102', 'doc', '{"docs": [{"id": "stk-dr-f68458", "n": "Dr. A Saadi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "أنصح فيه\n\nالدكتور عبدالعزيز السعدي\nصار لي موقفين معاه\nالموقف الأول بداية السمستر طردني من الكلاس لأني جيت متأخر أزيد من خمس دقائق يمكن ست أو سبع دقائق\nوبعدين خلال السمستر لاحظت أنه يدخل بعض الناس اللي متأخرين نفس الوقت!!!\nالموقف الثاني نهاية السمستر\nكان باقي لي ثلاث درجات على الـ A يعني 0.75%\nوما رضى يعطيني إياهم وحاولت معه واجد بس ما في أمل\n\nبالنسبة للشرح فشرحه ممتاز ، دائما يشرح على السلايدات، بعض الأحيان يحل مسائل على السبورة أو يستخدمها للإيضاح ، سلايداته ممتازة، تذاكر منها حق الكوزات والمياجر بل وحتى الفاينال تكفي وتوفي\n\nطريقة التحضير ورقة يعطيها بعد عشر دقائق، بعض الأحيان نصف الكلاس، بعض الأحيان قريب من نهاية الكلاس، يعني ما لها وقت، تمر على كل التلاميذ\nوينادي بالأسماء والأرقام بين وقت وآخر، يعني ما تقدر تحضر زميلك\nالتأخير حد أقصى خمس دقائق، أزيد من كذا يطردك من الكلاس، بعض الأحيان يمشيها، ويحرق قلب اللي انطرد اليوم اللي قبل!\n\nالكوزات: متوسطة، بس تذاكر السلايدات وتحل المسائل اللي فيها تجي وتفلفل الكوز\n\nالتقيم النهائي: B+ نفس التقييم اللي عطاني إياه 🤠\n\nالصوت: واضح والأكسنت ممتازة\n\nإضافات: ما أحسه يتساعد في الدرجات، متشدد في التصحيح، ولا يتساعد في الغياب أو غير ذلك، حقك تآخذه. عطانا مشروع برزنتيشن في كمستري 102 مكون من قروبات، ومشروعنا كان من أفضل المشاريع حسب ما هو نفسه قال، وبعدين أعطى قروبنا 8 من 10 وباقي القروبات 8.5 فصاعدا، مع أنه على مستوى الإلقاء والسلايدات والتلخيص كنا أفضل من أغلب القروبات بواجد.\nحسيت أنه ظلمنا في هذه النقطة.\n\nنصيحة: بعد كل كوز راجعه وتابع أخطائك في الكوز، وناقشه في الدرجة، وإن شاء الله تطلع بـ A+", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p781444-chem102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/a-saadi/68458/29", "user": "hsn3d", "ts": 1296825262000, "tid": 68458, "pn": 29}}]}', 1296825262000, 1794766199, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-ad0rs-chem102', 'stk-ad0rs', 'CHEM 102', 'doc', '{"docs": [{"id": "stk-dr-f68458", "n": "Dr. A Saadi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CHEM 102 LEC T132\nالتحضير :\nورقة تمر عالطلاب (ثلاث سكاشن مع بعض)\nما أنصحك تحضر لخويك\nلإنه غالبا يتأكد نهاية الكلاس من الأسماء واللي خويه حضره ياخذ 0\nطريقة الشرح :\nمن السلايدات - شرح واضح ويتجاوب مع أي سؤال\nالمياجر:\nكومون\nالفاينلات :\nكومون\nالقريد النهائي:\nA+\nالصوت:\nواضح (نص عربي نص انقلش)\nإضافات :\nفي الكورس ذا همك الوحيد الشرح\nلإن الدكتور مابيده يساعدك (مياجر وفاينلات كومون والكلاس وورك normalized)\n🌹", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1375686-chem102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/a-saadi/68458/42", "user": "ad0rs", "ts": 1401675879000, "tid": 68458, "pn": 42}}, {"id": "stk-dr-f118605", "n": "أ. عبد الله الأحمدي", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CHEM 102 REC T132\nالتحضير :\nمافي تحضير (شخصيا ما حضرت غير 4-5 مرات طوال السمستر)\nطريقة الشرح :\nشرحه ممتاز ويتجاوب مع الأسئلة\nالكويزات :\nسهلة غالبا (سؤال واحد اللي يكون فيه trick)\nالقريد النهائي:\nB+\nالصوت:\nشبه منخفض\n🌹", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1375687-chem102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/118605/18", "user": "ad0rs", "ts": 1401676128000, "tid": 118605, "pn": 18}}]}', 1401675879000, 1794766199, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-hamza_alnasser-chem102', 'stk-hamza_alnasser', 'CHEM 102', 'doc', '{"docs": [{"id": "stk-dr-f68458", "n": "Dr. A Saadi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Chem 102 Term 152\n\nالتحضير : ورقة فيها الأرقام الجامعية وتكتب اسمك قدام رقمك, التأخير زيادة عن 10 دقايق ما راح يخليك تدخل.\n\nطريقة الشرح : من الشرائح, شرحه حلو وتقدر تفهم عليه, وميزته أن ما يسرع كثير يعني يمشي حبه حبه بحيث يخليك تفهم المفاهيم صح.\nالكويزات : كان الدكتور البيطار اللي يعطينا وياها. وكانت سهلة إلى متوسطة بس تحتاج تذاكر وتتابع\nالمياجر: -\nالفاينلات : -\nالقريد النهائي: B+\nالصوت: واضح ومسموع\nإضافات : الدكتور خلوق ومتعاون مع الطلاب وشريح. من أحلى الكورسات اللي أخذتها, كورس ممتع جدا. وعموما في الكيمياء تحتاج تتابع أول بأول.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1446383-chem102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/a-saadi/68458/44", "user": "Hamza_Alnasser", "ts": 1460375813000, "tid": 68458, "pn": 44}}]}', 1460375813000, 1794766199, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-rashid_a-chem102', 'stk-rashid_a', 'CHEM 102', 'doc', '{"docs": [{"id": "stk-dr-f68458", "n": "Dr. A Saadi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "TERM 162 - CHEM 102\nلتحضير: يمرر ورقة والطلاب يحضرون بأنفسهم , اذا تأخرت اكثر من ربع ساعة ما يدخلك\nطريقة الشرح: يفتح السلايدات ويشرح منها وما يحب احد يقاطعه اثناء الشرح + الي يشوفه جالس على جواله يجلده بكم سؤال عشان ينتبه معاه\nالمياجر: المعلم كان يكتب المياجر\nالفاينلات: المعلم الي كتب الفاينل\nالقريد النهائي: أعطيه b\nالصوت: عادي\nإضافات: الدكتور مو من النوع الي يلاحق الطالب عشان درجاته , اهم شي توصلك المعلومة وانت بكيفك.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1474381-chem102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/a-saadi/68458/45", "user": "Rashid_A", "ts": 1496414873000, "tid": 68458, "pn": 45}}, {"id": "stk-dr-f176822", "n": "Dr. Ali Rinaldi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "TERM 162 - CHEM 102 (RECITATION(\nالتحضير : على حسب اذا في كويز او لا\nطريقة الشرح : شرح لنا 3 مرات للامانة سيئ بالنسبة لي , كأنه يقرا بشكل عادي\nالكويزات : متوسطة الصعوبة الى سهلة\nالمياجر: -\nالفاينلات : -\nالقريد النهائي: C+\nالصوت: كويس لكن اللهجة لك عليها\nإضافات : -", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1474383-chem102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ali-rinaldi/176822/2", "user": "Rashid_A", "ts": 1496415199000, "tid": 176822, "pn": 2}}, {"id": "stk-dr-f68542", "n": "Dr. Mohammad Wazeer", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "TERM 162 - CHEM 102 (LAP(\nالتحضير : كان لاب بس لو تتأخر ربع ساعة يخصم عليك من البريلاب\nطريقة الشرح : شرحه عادي واحيانا ما تفهم منه , كان يجي دكتور ثاني يساعده لان له 5 سنين ما درس المادة\nالكويزات : -\nالمياجر:-\nالفاينلات :-\nالقريد النهائي: C وزيادة\nالصوت: عادي\nإضافات : المدرس يخصم بشكل مو طبيعي يعني غلط ينخصم عليه درجتين يروح يخصم خمس.\nوهمه الطالب يخلص بسرعة عشان يمشي هو , كذا مرتين خلصو الطلاب كلهم وبقيت انا وخويي جلس يزعجنا يلا خلصو ويلا ابغى امشي وكانت الساعة 3 ونص !!", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1474384-chem102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammad-wazeer/68542/38", "user": "Rashid_A", "ts": 1496415595000, "tid": 68542, "pn": 38}}]}', 1496414873000, 1794766199, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-ahmed1-chem102', 'stk-ahmed1', 'CHEM 102', 'doc', '{"docs": [{"id": "stk-dr-f68544", "n": "Dr. M.b. Fettouhi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CHEM 102 LAB - 211\nالدكتور ممتاز من ناحية الشرح ويوضح لك المطلوب منكم حتى لو في وسط التجربة ويساعدك فيها واخلاقه جدا ممتازة وتصحيحه كويس تاخذ بين ال 7.5 الى 9 كل تجربة تقريبا ( ما يعطي فل !) بس كويزاته في البداية كانت عبيطة شوي لازم تكون فاهم التجربة قبل ما تجي عشان تحل ولا ما بتحل الكويز وفي النهاية خلاها سهلة وقام يجيب اخر صفحتين في المانوال و كنا نطول في التجارب فلا تستغرب اذا كنت تطلع 5 المغرب معاه واحيانا اكثر ! تقريبا ذي صارت ثلاث مرات لي مرتين منها كل الطلاب ما طلعوا الا بعد 5 ومرة انا تأخرت وعطاني فرصة اكمل! واللاب اللي جنبنا كان يطلعون قبل فنصيحة اذا دوامك مضغوط في يوم اللاب لا تنزل معاه.\n\nالقريد النهائي : +B", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1533093-chem102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/m-b-fettouhi/68544/25", "user": "Ahmed1", "ts": 1639778504000, "tid": 68544, "pn": 25}}, {"id": "stk-dr-f68458", "n": "Dr. A Saadi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CHEM102 - Term 211\n\nالتحضير : كان عنده طريقة جديدة في التحضير بحيث انه قال لنا اختاروا اماكن لكم وراح يصير لكم لنهاية الترم وعنده ورقة ويشوف الكرسي الفاضي ويغيب الطالب، مو كل يوم يحضر بس غالبها يعني ويعطي غيابين فري\nطريقة الشرح : من السلايدات اللي هو مسويها شرحه كان جيد جدا إلى ممتاز الا في بعض الشباتر كان مستعجل فيها وما شرحها بالشكل المطلوب يمكن السبب انه من زمان ما درس الكورس، عموما حسيت الدكتور ممتاز .\nالكويزات : عند دكتور ثاني\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي:ِِ A\nالصوت: مسموع وواضح رغم انه الكلاس كان في قاعة فيها ازعاج مكيفات\nإضافات : انصح في الدكتور اذا شفت سكشنه مفتوح، مثل ما قلت في غالبية الشباتر ما كنت احتاج ارجع للكتاب افهم من شرحه غالب الدرس 👍", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1533114-chem102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/a-saadi/68458/49", "user": "Ahmed1", "ts": 1639972777000, "tid": 68458, "pn": 49}}, {"id": "stk-dr-f152614", "n": "Dr. A Al-Betar", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CHEM 102 Term - 211 (Recitation only)\n\nالتحضير: يحضر بأوراق الكويز، واذا مافيه كويز فيه ورقة تمر على الكلاس.\n\nالشرح: ما اقدر اقيمه بشكل كامل بس من شرحه في الريسايتيشن اشوف شرحه حلو فيه بعض النقاط ما كنت افهمها مع دكتور اللكشر وهو يشرحها بشكل افضل\n\nالكويزات: سهلة جدا، يجيب كم سؤال من اسئلة الريسايتيشن و الاولد،\nبشكل عام كويزاته سهلة وتقدر تضمنها بس انتبه ترا كويزاته كانت رتن وتصحيحه خسف يا يعطيك فل على السؤال او صفر ما يعطي بارشل 😅\n\nالصوت: ضعيف نوعا ما\n\nالقريد النهائي: B+\n\nاضافات: الدكتور طيب جدا كمعاملة و اشوفه ممتاز للسيلف ستدي", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1533170-chem102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/a-al-betar/152614/11", "user": "Ahmed1", "ts": 1640432826000, "tid": 152614, "pn": 11}}]}', 1639778504000, 1794766199, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-saleh28-chem102', 'stk-saleh28', 'CHEM 102', 'doc', '{"docs": [{"id": "stk-dr-f68488", "n": "Dr. Ghassan Oweimreen", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "التحضير :\nبشكل يومي ورقه تلف بس اذا شاف الشعب يلف ويدور يبدأ ينادي الاسماء\nطريقة الشرح :\nمممممممممممممممممتاااااااااااااااااااااااااااااااااااااااااااااااااااااااااااااازة اتعب وانا اقول ممتازة شي رهيب جدا بصراحه للحين من افضل الدكاترة اللي درسوني بالجامعه ممتاز جدا جدا انصح فيه\nالكويزات :\nمتوسطه مايله للصعوبة احيانا قليلة\nالمياجر:\nكومون\nالفاينلات :\nكومون\nالقريد النهائي: A +\nالصوت: عالي وواضح … يمكن للي يجلس ورى يكون لا بس انا كنت بالنص اجلس واحسه اوكي\nإضافات :\nدكتووور اخلاااااااااااااااااااااااااااااااق يعني من جد كنت استمتع معه بالكلاس خفيف دم ومرح\nمو من النوع اللي يدخل قالب اخلاقه بالعكس يضحك ويمزح مع الطلاب …\n\nانصح فيه بقوة ولا يغرك انه شايب ترى ممتاز\nاذا لقيته في كيمستري 102 لاتتردد مع انه ضعيف شوووي في الاورقانك وماكان عندنا الا شابتر واحد بس يعني مايسبب مشاكل", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p867406-chem102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ghassan-oweimreen/68488/18", "user": "Saleh28", "ts": 1310496053000, "tid": 68488, "pn": 18}}]}', 1310496053000, 1794766199, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-hashim_ali-chem102', 'stk-hashim_ali', 'CHEM 102', 'doc', '{"docs": [{"id": "stk-dr-f68544", "n": "Dr. M.b. Fettouhi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CHEM 102 LAB - 182\n\nأشوف الناس يبالغون في ذمه في اللاب ، نظامه كل لاب فيه كويز بسيط لو تحضر 20د له تحله كله ( بالعادة سؤال واحد من بين السطور )، بعدها يشرح التجربة بالتفصيل الممل مع البروسيجر وو .\nتجارب 102 بطبيعتها طويلة فعشان كذا كنا نطول ببعض اللابات ، اشوفه متساعد وإذا فيه نقطة ما فهمتها يشرحها لك ويوضحها\nعن نفسي كنت استمتع في لابات 102 معه\n\nالقريد النهائي : +A", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1516432-chem102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/m-b-fettouhi/68544/23", "user": "Hashim_Ali", "ts": 1571961708000, "tid": 68544, "pn": 23}}]}', 1571961708000, 1794766199, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user5771-chem102', 'stk-user5771', 'CHEM 102', 'doc', '{"docs": [{"id": "stk-dr-f68546", "n": "د. مونج", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "تعامله مو قد كذا\nبس والله شرحه ممتاز ويعيشك جو\nودايم أمثلته من سابك وارمكو وشركات\nكوزاته سهله\nالتحضير سهالات\n\nهذا الكلام كمستري 102 سمستر 103", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p970298-chem102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/68546/15", "user": "user5771", "ts": 1326873368000, "tid": 68546, "pn": 15}}]}', 1326873368000, 1794766199, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-sa3b_jlioji-chem102', 'stk-sa3b_jlioji', 'CHEM 102', 'doc', '{"docs": [{"id": "stk-dr-f80958", "n": "د. أسامة البجيرامي", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "بـ كل امانة دكتور ولا اروع …\n\nيهتم بـ مصلحة الطالب كثيرا … ويتعاون معاك لاقصى حد …\nيشرح عن طريق البوربوينت … ويقول انها تغنيك عن الكتاب …\nكويزاته سهلة …\nاسبوعيا يوزع اسئلة ريفيو ع كل شابتر … فيها الاسئلة المهم ع الباب …\nالتحضير كان يحضر بداية السمستر ولما شاف كثير يوقعوا عن اخويائهم … قال اللي يبغى يحضر حياه واللي مايبغى بكيفه …\n\nومتعاون جدا لو رحتله في الاوفيس اور … او حتى برا الاوفيس اور …\n\nهو يقول … لو لقيتني في اي مكان … في الاوفيس في السيب في السناك بار وعندك سؤال تعال اسئلني …\n\nالله يسعد الدكتور ويوفقه … من احسن الدكاترة اللي مروا علي في الجامعة …\n\n*انا منزل عنده لكتشر chem102\n\n.\n.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p585572-chem102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/80958/7", "user": "Sa3b_JLioJI", "ts": 1270722739000, "tid": 80958, "pn": 7}}]}', 1270722739000, 1794766199, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user4988-chem102', 'stk-user4988', 'CHEM 102', 'doc', '{"docs": [{"id": "stk-dr-f80958", "n": "د. أسامة البجيرامي", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "092\nchem 102\n\nأستاذ أسامة البجيرامي …\nالله يذكره بالخيييييييييييييييييييييييير …\n\nبدون مبالغة … من أفضل مدرسي الكميستري على الإطلاق … لاااا … أفضل مدرس كيمستري في الديبارتيمنت كله … مع فائق إحترامي للبقية …\n\nكلما أمر على مكتبه اللي في مبنى 4 , ادعي له …\n\nالرجال هذا ما يعاملك كمدرس و طالب … لا … يتعامل معك كصديق …\nشرحه ذهب … تركيزك معاه في المحاضرة لها أهمية ما تتصوروها … يعلمك تذاكر من إيش عشان تجيب درجة طيبة في المياجر …\n\nالتحضير : يمرر ورق على الكلاس … لكنه يعرف و حاط في رأسه إن عدد التواقيع راح تكون اكثر من الطلاب الحاضرين … بس ما همه لأن اللي يغيب غالباً راح يأكلها …\n\nالكويزات : على الشرح … ما فيه شيء معقد بتاتاً … تصدقوا إنه يساعد إذا شاف السكشن حاسوا في سؤال ؟؟؟؟ لدرجة إنه أحياناً يأشر للجواب بطريقة مباشرة او غير مباشرة …\nفي هذه النقطة بالتحديد خلت الدوافير -:p- يحقدون عليه … من بين حججهم إنهم يذاكروا و يذاكروا … آخر شيء الجميع يأخذوا درجات حلوة في الكلاس وورك …\nليه الحسد ؟؟؟ خلوا الواحد يحس إنه سوى شيء … ولو كان النظام آفرج …\n\nالقريد النهائي: أعطيه … همممممممممممم…\na++++++++++++++++++++++++++++++\n\nالصوت:واااااااااضح جداً… الأكسنت حقه مرة خطير\n\nإضافات :\nزي ما قالوا الشباب … نزل عنده و انت مغمض و بدون تردد … سواءً في كيم 101 أو 102 أو لاب أو ليكتشر … أهم شيء لا يفوتك …\nأخخخ … لو كنت عارف كنت نزلت عنده 101 … لكن الله ما أراد\n\nحسافة إنه ما عنده كورس ثالث إلا في CHEM 520 …\n\nالله يوفقه دنيا و آخرة\n\nو الله الهادي إلى سواء السبيل", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p729304-chem102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/80958/15", "user": "user4988", "ts": 1288434522000, "tid": 80958, "pn": 15}}]}', 1288434522000, 1794766199, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-biskrem-chem102', 'stk-biskrem', 'CHEM 102', 'doc', '{"docs": [{"id": "stk-dr-f81012", "n": "Dr. Mohammad Al-Imam", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "يدرسني ريستشن كمستري 102\n\nطريقة الشرح : يستخدم السبورة ويشرح الكونسبت ثم يحل الأسئلة\n\nالكويزات : متوسطة إلى سهلة ,أغلب الأسئلة تركز على الكونسبت ,كل اسبوع شابتر\n\nالمياجر والفاينال : كومن\n\nالصوت : منخفض قليلا", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p514473-chem102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammad-al-imam/81012/3", "user": "Biskrem", "ts": 1262460954000, "tid": 81012, "pn": 3}}]}', 1262460954000, 1794766199, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user9305-chem102', 'stk-user9305', 'CHEM 102', 'doc', '{"docs": [{"id": "stk-dr-f118605", "n": "أ. عبد الله الأحمدي", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Chem 102 rec t132\n\nالرجال أخلاق عالية ومعاملة راقية جداً في المحاضرة وفي الساعات المكتبية، كانت كل محاضرة ريسايتيشن فيها كويز فما كان يشرح الا 30 دقيقة، لكن بالمجمل شرحهه ممتاز. كان يحل أسئلة الكويزات بعد ما ينتهي الكويز مباشرة في معظم الاحيان.\n\nعيبه الوحيد هو ان تصحيحه شديد، لكن ما دامت المسألة آفرج فالأمر مقبول.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1414202-chem102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/118605/19", "user": "user9305", "ts": 1416520263000, "tid": 118605, "pn": 19}}]}', 1416520263000, 1794766199, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-s.q-chem102', 'stk-s.q', 'CHEM 102', 'doc', '{"docs": [{"id": "stk-dr-f172597", "n": "Dr. Abdul Malik", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CHEM102 - REC term 211\n\nالتحضير : يحضر بالكويز واذا ما فيه كويز يرسل رابط فورمز فالتيمز\n\nطريقة الشرح : اول ما يبدا الكلاس يوزع علينا الكويز وبعدها يعطينا 25 دقيقة بعدها يسحب أوراق الكويز ويعطينا أسئلة نحلها في 10 دقائق بعدها يحل الأسئلة معنا ، الصراحة هذا عيبه الوحيد ان شرحه سيء في حل المسائل ممكن بسبب صوته المنخفض والممل\n\nالكويزات : من سهلة الى متوسطة\n\nالمياجر: كومن\n\nالفاينلات : كومن\n\nالقريد النهائي: B+ عشان شرحه ولا هو كشخص يستاهل A++++++++\n\nالصوت: اكسنت هندي مو واضح و منخفض\n\nإضافات:\n1- الدكتور طيب وحبيب الى ابعد حد مستحيل يزعل منك مهما صار\n\n2- متعاون جدا مع الطلاب ، كان يمشي الطلاب بعد الكويز اذا كلموه\n\n3- من وجهة نظري اشوف ان الدكتور خيار ممتاز جدا للريسايتيشن واللاب لان أهمية الشرح فيهم مو زي أهميته في الليكشر عشان كذا انا ما انصح فيه ابدا لليكشر", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1533347-chem102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-abdul-malik/172597/8", "user": "S.Q", "ts": 1641560770000, "tid": 172597, "pn": 8}}, {"id": "stk-dr-f118609", "n": "أ. وائل محفوظ", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CHEM102- LAB term 211\n\nالتحضير : بأوراق الكويز والريبورت ، ما عنده شي اسمه تأخير لانه حتى هو بعض الاحيان يجي متأخر\n\nطريقة الشرح : في البداية يوزع عيلنا اوراق الكويز ويعطينا تقريبا ربع ساعة بعدها يسحب الاوراق ويجمعنا عند السبورة ويبدا يشرح التجربة ، اذا كانت التجربة طويلة يشرحها على اجزاء واول ما يخلص شرح الجزء يخلينا نطبق عليه ، اذا التجربة بسيطة يشرحها كلها بعدين يخلينا نطبق ، شرحه جيد لكن يعيبه انه يخرج عن الموضوع كثير ويضيع الوقت بالفاضي\n\nالكويزات : مثل ما ذكرت بداية كل لاب يعطينا بري كويز للتجربة الي بناخذها ، الصراحة اغلب كويزاته صعبة و الكل يشتكي منها خصوصا انه يعتمد في اسألته على اسماء المركبات بالانجليزي وانك لازم تكتب معادلة موزونة لتفاعل معين والاغلب ما يكون عارف الاشياء هذي بالنص ف كل واحد يهبد من راسه ، بس الصدق عطانا كم كويز سهل عشان يرفع الافرج شوي ( طريقة المذاكرة للكويز من الكتاب تروح للتجربة الي بتاخذها فاللاب الجاي حسب الجدول الموجود فالسيلبس وتقراها )\n\nالمياجر: -\n\nالفاينلات : فاينل لاب راح يكون على تجربة واحدة من التجارب الي اخذتها فالترم\n\nالقريد النهائي: A ( ال+ شلتها عشان كويزاته ولا هو يستاهلها وبجدارة )\n\nالصوت: واضح\n\nإضافات :\n1- الدكتور طيييب الى ابعد حد وروحه حلوة ويحب ينكت مع الطلاب و يجاوب على اي سؤال تسأله و يطلعك اذا خلصت الريبورت\n\n2- يصنع جو أخوي بين الطلاب لانه بيقسمكم بداية الترم الى مجموعات كل مجموعة فيها شخصين وكل مجموعة لها ريبورت واحد و فبعض اللابات يخلي كل مجموعتين لهم ريبورت واحد ( طبعا الفاينل لاب راح يكون فردي )\n\n3- تصحيحه للريبورت اسطوري ويمشِّي كثييييير لانه متفهم لوضع الطلاب وعارف ان وقت اللاب طويييل فأكيد التركيز ما راح يكون فل طول اللاب\n\nاذا لقيته ف اي لاب لأي مادة ثانية راح انزل عنده وانا مغمض ، انصح به وبقوة", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1533376-chem102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/118609/16", "user": "S.Q", "ts": 1641727701000, "tid": 118609, "pn": 16}}]}', 1641560770000, 1794766199, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-khalid-f10-chem102', 'stk-khalid-f10', 'CHEM 102', 'doc', '{"docs": [{"id": "stk-dr-f118612", "n": "أ. عبد الغفار محمد", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ترم 113 - لاب chem 102\n\nطريقة الشرح : يجي اللاب ويشرح لكم الاشياء الاساسية في التجربة وكيف تسوونها وبعدين يقول لكم ابدوا التجربة ومن بداية الترم بيحطكم في في مجموعات كل مجموعة طالبين يشتغلون مع بعض\n\nالكويزات : تقريبا كل لاب وكلها من البري لاب يقول لكم اقطعوا الورقة وحلوا\n\nالفاينلات : قسم النظري في الفاينال لاب يجيب لكم اسئلة سهلة بس حقة فلسفة\nالقريد النهائي: B+\n\nالصوت:جيد\nإضافات :المدرس حبوب وطيب طبعا المدرس سوداني\n\nبس اذا جيت تساله سؤال يتعلق بالريبورت ما بيجاوبك او اذا جاوبك بيجاوبك بشكل عام", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1074024-chem102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/118612/6", "user": "khalid-f10", "ts": 1343684948000, "tid": 118612, "pn": 6}}]}', 1343684948000, 1794766199, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-tweiti-chem102', 'stk-tweiti', 'CHEM 102', 'doc', '{"docs": [{"id": "stk-dr-f152614", "n": "Dr. A Al-Betar", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Chem 102-212\nالتحضير : ورقة يمررها الطلاب\nالشرح : متوسط أو أقل\nالكويزات : سهله، أغلب الأسئلة تجي من السامبل أو السلايدات أو الريس.\nالصوت: ضعيف\nالقريد النهائي : B\nإضافات : الدكتور تصحيحه سيء، تعامله مع الطالب فوق الممتاز، كان ما يدقق على التحضير لين شاف القاعة فاضية.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1535047-chem102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/a-al-betar/152614/12", "user": "Tweiti", "ts": 1660703876000, "tid": 152614, "pn": 12}}]}', 1660703876000, 1794766199, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
